{
  "packet_id": "H6-T03-3",
  "claim_id": "C009",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C009.component",
    "value": "Evidence retrieved afterward that documents prior approval must be distinguished from approval itself granted afterward.",
    "scope": "Historical record reconstruction; evidence-retrieval time and approval time are different considerations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly requires distinguishing later retrieval of prior-approval evidence from later approval."
    }
  },
  "signal_basis": {
    "component_id": "C009.signal_basis",
    "value": "Compare order-placement timestamps with purchasing records, meeting minutes and delegated-authority forms to establish whether authorized approval preceded placement, preserving provenance and distinguishing retrieval time from approval time.",
    "scope": "Reconstruction of each flagged order's approval chronology; later approval does not establish approval before placement.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the comparison procedure, provenance requirement and temporal limitation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C009.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The distinction is licensed directly by the temporal record comparison and requires no unresolved empirical relation."
    }
  },
  "rationale": "Retrieving evidence after purchase and granting approval after purchase are different events. Evidence found later can document approval that already existed before placement; approval granted later cannot establish that chronology. The operation therefore licenses the claimed distinction within historical record reconstruction.",
  "uncertainty": "Individual records may leave approval timing unresolved, but that does not undermine the required distinction.",
  "anomalies": []
}
